public static void main(String[] args) throws Exception {
    Scanner sc = new Scanner(System.in);
    List<Integer> sequence = new ArrayList<>();
    int Q = sc.nextInt();
    for (int i = 0; i < Q; i++) {
        int a = sc.nextInt();
        if (a == 1) {
            int x = sc.nextInt();
            sequence.add(x);
        } else if (a == 2) {
            int k = sc.nextInt();
            System.out.println(sequence.get(sequence.size() - k));
        }
    }
    sc.close();
}
